      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "for p in \"${MOOTX01_BIN:-}\" \"$HOME/.mootx01/bin/mootx01\" \"$HOME/.local/bin/mootx01\" /opt/homebrew/bin/mootx01 /usr/local/bin/mootx01 /home/linuxbrew/.linuxbrew/bin/mootx01 /usr/bin/mootx01; do [ -x \"$p\" ] && exec \"$p\" codex-hook SessionStart; done; exit 0",
